17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    /** Dedicated audit trail logger; carries a line for each successful owner create. */
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /**
108	     * Normalize the optional email: absent stays absent; when present it must be syntactically
109	     * valid and is lower-cased. Returns {@code false} if present but invalid.
110	     */
111	    private boolean normalizeEmail(Owner owner) {
112	        String email = owner.getEmail();
113	        if (email == null || email.isEmpty()) {
114	            owner.setEmail(null);
115	            return true;
116	        }
117	        if (!EMAIL_PATTERN.matcher(email).matches()) {
118	            return false;
119	        }
120	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
121	        return true;
122	    }
123	
124	    /**
125	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
126	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
127	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
128	     *
129	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
130	     *         a valid E.164 number.
131	     */
132	    private static String toE164(String raw) {
133	        if (raw == null) {
134	            return null;
135	        }
136	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
137	        String digits;
138	        if (cleaned.startsWith("+")) {
139	            digits = cleaned.substring(1);
140	        } else {
141	            if (cleaned.startsWith("0")) {
142	                cleaned = cleaned.substring(1);
143	            }
144	            digits = "61" + cleaned;
145	        }
146	        if (!digits.matches("\\d{8,15}")) {
147	            return null;
148	        }
149	        return "+" + digits;
150	    }
151	
152	    /**
153	     * Build the customer code {@code <CITY3>-<LAST3>-<NNNN>}: CITY3 is the upper-cased first three
154	     * letters of the city, LAST3 the upper-cased first three letters of the last name and NNNN a
155	     * per-city 4-digit zero-padded sequence equal to one more than the owners already in that city
156	     * (e.g. {@code SYD-SMI-0007}).
157	     */
158	    private String nextCustomerCode(String city, String lastName) {
159	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
160	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
161	        int sequence = 1;
162	        for (Owner existing : this.clinicService.findAllOwners()) {
163	            if (city.equalsIgnoreCase(existing.getCity())) {
164	                sequence++;
165	            }
166	        }
167	        return String.format("%s-%s-%04d", city3, last3, sequence);
168	    }
169	
170	    /** Common street-type abbreviations expanded during address normalization. */
171	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
172	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
173	
174	    /**
175	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
176	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
177	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
178	     */
179	    private static String normalizeAddress(String value) {
180	        if (value == null) {
181	            return "";
182	        }
183	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
184	        if (collapsed.isEmpty()) {
185	            return "";
186	        }
187	        String[] tokens = collapsed.split(" ");
188	        StringBuilder sb = new StringBuilder(collapsed.length());
189	        for (int i = 0; i < tokens.length; i++) {
190	            if (i > 0) {
191	                sb.append(' ');
192	            }
193	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
194	        }
195	        return sb.toString();
196	    }
197	
198	    /**
199	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
200	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
201	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
202	     */
203	    private static String normalizeForHousehold(String value) {
204	        if (value == null) {
205	            return "";
206	        }
207	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
208	    }
209	
210	    /**
211	     * Return the owners that already share this owner's household, i.e. have the same last name and
212	     * address compared case-insensitively with collapsed whitespace.
213	     */
214	    private List<Owner> householdMembers(Owner owner) {
215	        String lastName = normalizeForHousehold(owner.getLastName());
216	        String address = normalizeForHousehold(owner.getAddress());
217	        List<Owner> members = new java.util.ArrayList<>();
218	        for (Owner existing : this.clinicService.findAllOwners()) {
219	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
220	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
221	                members.add(existing);
222	            }
223	        }
224	        return members;
225	    }
226	
227	    /**
228	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
229	     * last name and address compared case-insensitively with collapsed whitespace.
230	     */
231	    private boolean sharesHouseholdWithExisting(Owner owner) {
232	        return !householdMembers(owner).isEmpty();
233	    }
234	
235	    /**
236	     * Count the existing owners that share this owner's first name and last name, compared
237	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
238	     */
239	    private int namesakeCount(Owner owner) {
240	        String firstName = owner.getFirstName();
241	        String lastName = owner.getLastName();
242	        int count = 0;
243	        for (Owner existing : this.clinicService.findAllOwners()) {
244	            if (firstName != null && lastName != null
245	                && firstName.equalsIgnoreCase(existing.getFirstName())
246	                && lastName.equalsIgnoreCase(existing.getLastName())) {
247	                count++;
248	            }
249	        }
250	        return count;
251	    }
252	
253	    /**
254	     * A stable, shared household identifier derived from the normalized last name and address, so every
255	     * owner in the same household deterministically resolves to the same value.
256	     */
257	    private static String householdIdFor(Owner owner) {
258	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
259	        try {
260	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
261	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
262	            StringBuilder sb = new StringBuilder(24);
263	            for (int i = 0; i < 12; i++) {
264	                sb.append(String.format("%02X", digest[i]));
265	            }
266	            return sb.toString();
267	        }
268	        catch (java.security.NoSuchAlgorithmException e) {
269	            throw new IllegalStateException(e);
270	        }
271	    }
272	
273	    /** Maximum number of owners permitted in a single city. */
274	    private static final int CITY_CAPACITY = 50;
275	
276	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
277	    private static final int DAILY_CREATE_LIMIT = 100;
278	
279	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
280	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
281	
282	    /**
283	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
284	     * Used to enforce the per-city capacity on create (before this owner is saved).
285	     */
286	    private int cityOwnerCount(Owner owner) {
287	        String city = owner.getCity();
288	        int count = 0;
289	        for (Owner existing : this.clinicService.findAllOwners()) {
290	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
291	                count++;
292	            }
293	        }
294	        return count;
295	    }
296	
297	    /**
298	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
299	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
300	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
301	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
302	     */
303	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
304	        switch (date.getDayOfWeek()) {
305	            case SATURDAY:
306	                return date.plusDays(2);
307	            case SUNDAY:
308	                return date.plusDays(1);
309	            default:
310	                return date;
311	        }
312	    }
313	
314	    /**
315	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
316	     * per-day create limit on create (before this owner is saved).
317	     */
318	    private int ownersRegisteredOn(java.time.LocalDate day) {
319	        int count = 0;
320	        for (Owner existing : this.clinicService.findAllOwners()) {
321	            if (day.equals(existing.getRegistrationDate())) {
322	                count++;
323	            }
324	        }
325	        return count;
326	    }
